<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pacientes</title><style>body{max-width:1100px;margin:40px auto;background:#fcfafb;color:#332d35;font:14px Arial}a{color:#bd3168;text-decoration:none}h1{font-size:32px}.top,.row,.stats{display:flex;gap:16px;align-items:center}.top{justify-content:space-between}.primary,button{background:#dc4f87;color:white;border:0;border-radius:8px;padding:11px 14px;font-weight:bold}.search{display:flex;margin:25px 0}.search input{flex:1;padding:12px;border:1px solid #eadde2;border-radius:8px}.stat,.table{background:#fff;border:1px solid #f0e6ea;border-radius:12px}.stat{padding:17px;flex:1}.stat b{display:block;font-size:25px;margin-top:8px}.row{padding:14px;border-top:1px solid #f5edf0}.head{font-size:11px;color:#817780;text-transform:uppercase}.row>*{flex:1}.person{font-weight:bold}.person small{display:block;color:#198b69;margin-top:4px}.pending{color:#c98421!important}.last{color:#817780}@media(max-width:650px){body{margin:20px}.stats{flex-wrap:wrap}.stat{min-width:38%}.row>*:nth-child(2),.row>*:nth-child(3),.row.head{display:none}}</style></head><body><a href="{{ route('dashboard') }}">← Panel general</a><header class="top"><div><h1>Pacientes</h1><p>Administra la información e historial de tus pacientes</p></div><a class="primary" href="{{ route('pacientes.create') }}">＋ Nuevo paciente</a></header><form class="search"><input name="buscar" value="{{ $search }}" placeholder="Buscar por nombre, documento o teléfono…"><button>Buscar</button></form><section class="stats"><div class="stat">👥 Pacientes<b>{{ $totalPatients }}</b></div><div class="stat">🟢 Activos<b>{{ $activePatients }}</b></div><div class="stat">📅 Citas hoy<b>{{ $todayAppointments }}</b></div><div class="stat">⭐ Nuevos<b>{{ $newPatients }}</b></div></section><section class="table"><div class="row head"><div>Paciente</div><div>Documento</div><div>Teléfono</div><div>Última cita</div></div>@